":"sourceText","earliest_start":"nativeEarliestStart","schedule_text":"scheduleText","mention":"mention","created_at":"nativeCreatedAt","reviewed_at":"nativeReviewedAt","snapshot_id":"snapshotId","review_id":"reviewId","review_no":"reviewNo","catalogue_id":"catalogueId","catalogue_version":"catalogueVersion","git_blob_sha1":"gitBlobSha1","source_snapshot_id":"sourceSnapshotId","actor_kind":"actorKind","boundary_notes":"boundaryNotes","occupation_code":"occupationCode","manifest_hash":"manifestHash","decision":"decision","reviewer":"reviewer","reviewer_kind":"reviewerKind","notes":"notes","git_commit":"gitCommit","merge_evidence":"mergeEvidence","attestation_kind":"attestationKind","repository_verification":"repositoryVerification","scheme_code":"schemeCode"},"unknown_property_encoding":"jtf:UTF8-hex","node_iri_encoding":"urn:jobtology:node: plus SHA-256 of the exact native node ID UTF-8 bytes","edge_iri_encoding":"urn:jobtology:edge: plus the native edge ID","named_graph":"urn:jobtology:release: plus SHA-256 of the exact release ID UTF-8 bytes","schema_types":{"organization":"schema:Organization","jobPosting":"schema:JobPosting","occupation":"schema:Occupation","ncsClass":"schema:CategoryCode","ncsCompetency":"schema:DefinedTerm","ncsUnitFamily":"schema:DefinedTerm","qualification":"schema:EducationalOccupationalCredential","conceptScheme":"schema:DefinedTermSet","skill":"schema:DefinedTerm","majorConcept":"schema:DefinedTerm","course":"schema:Course","courseInstance":"schema:CourseInstance","place":"schema:Place"},"schema_literal_aliases":{"name":"schema:name","title":"schema:title","source_url":"schema:url","date_posted":"schema:datePosted","closing_date":"schema:validThrough"},"schema_relation_aliases":{"POSTED_BY":"schema:hiringOrganization"},"notes":["Schema types apply to identity shells and their immutable revisions; changing values remain on revisions.","Native labels, field keys, values, ordered arrays, edge identities and qualifiers remain recoverable.","NCS competency units and unresolved unit families are distinct from generic skills.","ALIGNS_WITH/curriculum references are never promoted into SKOS exactMatch or ATTESTS.","No Person or private application node is an exportable native label."],"datetime_aliases":{"first_seen_at":"firstSeenAt","last_seen_at":"lastSeenAt","evaluated_at":"evaluatedAt","created_at":"createdAt","reviewed_at":"reviewedAt"},"date_aliases":{"earliest_start":"earliestStart"}},"schemas/product-occupations-v1.schema.json":{"type":"object","properties":{"schema_version":{"type":"string","minLength":1,"maxLength":4000,"enum":["hop-product-occupations-v1"]},"source_id":{"type":"string","minLength":1,"maxLength":4000,"enum":["INTERNAL_EDITORIAL"]},"catalogue_id":{"type":"string","minLength":1,"maxLength":4000,"enum":["product-occupations"]},"catalogue_version":{"type":"integer","minimum":1,"maximum":2147483647},"actor":{"type":"string","minLength":1,"maxLength":200},"actor_kind":{"type":"string","minLength":1,"maxLength":4000,"enum":["human","assistant"]},"scheme":{"type":"object","properties":{"code":{"type":"string","minLength":1,"maxLength":4000,"enum":["product-occupations"]},"name":{"type":"string","minLength":1,"maxLength":200},"description":{"type":"string","minLength":1,"maxLength":4000}},"required":["code","name","description"],"additionalProperties":false},"occupations":{"type":"array","minItems":4,"maxItems":4,"items":{"type":"object","properties":{"code":{"type":"string","minLength":1,"maxLength":4000,"enum":["AI_ENGINEER","BACKEND_DEVELOPER","FRONTEND_DEVELOPER","DATA_ANALYST"]},"name":{"type":"string","minLength":1,"maxLength":200},"description":{"type":"string","minLength":1,"maxLength":4000},"aliases":{"type":"array","maxItems":30,"items":{"type":"string","minLength":1,"maxLength":200}},"boundary_notes":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"string","minLength":1,"maxLength":4000}}},"required":["code","name","description","aliases","boundary_notes"],"additionalProperties":false}}},"required":["schema_version","source_id","catalogue_id","catalogue_version","actor","actor_kind","scheme","occupations"],"additionalProperties":false},"shapes.ttl":"# Combined v4 structural and publication profile.\n@prefix jt: <urn:jobtology:vocab:1:> .\n@prefix sh: <http://www.w3.org/ns/shacl#> .\n@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\n# Transport/evidence structure only. Passing this file is not publication approval.\njt:NativeNodeShape a sh:NodeShape ;\n  sh:targetSubjectsOf jt:nativeNodeId ; sh:nodeKind sh:IRI ;\n  sh:property [ sh:path jt:nativeNodeId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:nativeLabel ; sh:minCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:nativeContentHash ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:sparql [ sh:message \"Native node IRI must hash its exact native identifier.\" ;\n    sh:select \"\"\"PREFIX jt: <urn:jobtology:vocab:1:>\n      SELECT $this WHERE { $this jt:nativeNodeId ?id .\n        FILTER (STR($this) != CONCAT(\"urn:jobtology:node:\", SHA256(STR(?id)))) }\"\"\" ] .\n\njt:RelationShape a sh:NodeShape ; sh:targetClass jt:Relation ; sh:nodeKind sh:IRI ;\n  sh:property [ sh:path jt:nativeEdgeId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:nativeContentHash ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:nativePredicate ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[A-Z][A-Z_]*$\" ] ;\n  sh:property [ sh:path jt:nativeSubjectId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n  sh:property [ sh:path jt:nativeObjectId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n  sh:property [ sh:path rdf:subject ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ] ;\n  sh:property [ sh:path rdf:predicate ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ] ;\n  sh:property [ sh:path rdf:object ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ] ;\n  sh:sparql [ sh:message \"A reified relation must have matching in-graph endpoints and a direct triple.\" ;\n    sh:select \"\"\"PREFIX jt: <urn:jobtology:vocab:1:>\n      PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>\n      SELECT $this WHERE { $this rdf:subject ?s ; rdf:predicate ?p ; rdf:object ?o ;\n        jt:nativeSubjectId ?sid ; jt:nativeObjectId ?oid ; jt:nativeEdgeId ?eid .\n        FILTER (STR($this) != CONCAT(\"urn:jobtology:edge:\",STR(?eid)) ||\n          NOT EXISTS { ?s jt:nativeNodeId ?sid } || NOT EXISTS { ?o jt:nativeNodeId ?oid } ||\n          NOT EXISTS { ?s ?p ?o }) }\"\"\" ] .\n\njt:EntityShape a sh:NodeShape ; sh:targetClass jt:Entity ;\n  sh:property [ sh:path jt:entityId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:hasRevision ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:EntityRevision ] ;\n  sh:sparql [ sh:message \"A selected revision must belong to its identity shell.\" ;\n    sh:select \"\"\"PREFIX jt: <urn:jobtology:vocab:1:>\n      SELECT $this WHERE { $this jt:entityId ?id ; jt:hasRevision ?revision .\n        FILTER NOT EXISTS { ?revision jt:entityId ?id } }\"\"\" ] .\n\njt:RevisionShape a sh:NodeShape ; sh:targetClass jt:EntityRevision ;\n  sh:property [ sh:path jt:revisionId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:entityId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:payloadHash ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] .\n\njt:SourceRecordShape a sh:NodeShape ; sh:targetClass jt:SourceRecordEvidence ;\n  sh:property [ sh:path jt:sourceId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:sourceRecordId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:rawSha256 ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:normalizedHash ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:locator ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] .\n\njt:EvidenceShape a sh:NodeShape ; sh:targetClass jt:EvidenceSpan ;\n  sh:property [ sh:path jt:evidenceId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:excerpt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:excerptSha256 ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:startOffset ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 0 ; sh:lessThan jt:endOffset ] ;\n  sh:property [ sh:path jt:endOffset ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 1 ] ;\n  sh:property [ sh:path jt:offsetUnit ; sh:minCount 1 ; sh:maxCount 1 ; sh:hasValue \"UNICODE_CODE_POINT\" ] ;\n  sh:property [ sh:path jt:inArtifact ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:TextArtifact ] ;\n  sh:sparql [ sh:message \"The excerpt hash must match the exact exported Unicode text.\" ;\n    sh:select \"\"\"PREFIX jt: <urn:jobtology:vocab:1:>\n      SELECT $this WHERE { $this jt:excerpt ?text ; jt:excerptSha256 ?hash .\n        FILTER(SHA256(STR(?text)) != STR(?hash)) }\"\"\" ] .\n\njt:TextArtifactShape a sh:NodeShape ; sh:targetClass jt:TextArtifact ;\n  sh:property [ sh:path jt:artifactId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n  sh:property [ sh:path jt:textSha256 ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:sourceField ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:derivedFrom ; sh:minCount 1 ; sh:nodeKind sh:IRI ] .\n\njt:ReviewedClaimShape a sh:NodeShape ; sh:targetClass jt:DutyClaim, jt:SourceRequirementGroup ;\n  sh:property [ sh:path jt:claimId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n  sh:property [ sh:path jt:postingRevisionId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:evidencedBy ; sh:minCount 1 ; sh:class jt:EvidenceSpan ] ;\n  sh:property [ sh:path jt:reviewedBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:PostingReviewSelection ] .\n\njt:ConditionExpressionShape a sh:NodeShape ; sh:targetClass jt:ConditionExpression ;\n  sh:property [ sh:path jt:operator ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"atom\" \"all_of\" \"any_of\" \"if_then\" \"except\") ] ;\n  sh:or (\n    [ sh:property [ sh:path jt:operator ; sh:hasValue \"atom\" ] ; sh:property [ sh:path jt:hasChild ; sh:maxCount 0 ] ]\n    [ sh:property [ sh:path jt:operator ; sh:in (\"all_of\" \"any_of\") ] ; sh:property [ sh:path jt:hasChild ; sh:minCount 2 ; sh:class jt:ConditionExpression ] ]\n    [ sh:property [ sh:path jt:operator ; sh:in (\"if_then\" \"except\") ] ; sh:property [ sh:path jt:hasChild ; sh:minCount 2 ; sh:maxCount 2 ; sh:class jt:ConditionExpression ] ]\n  ) .\n\njt:ReleaseStructureShape a sh:NodeShape ; sh:targetClass jt:CorpusRelease ;\n  sh:property [ sh:path jt:selectedReleaseId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path jt:nativeGraphManifestHash ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:exportContractVersion ; sh:minCount 1 ; sh:maxCount 1 ; sh:hasValue \"hop-ontology-interchange-v4\" ] ;\n  sh:property [ sh:path jt:exportContractHash ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:property [ sh:path jt:exportReadMode ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"PREVIEW\" \"PUBLISHED\") ] .\n\n\n# Observations are bound to the same entity and exact revision in this release.\njt:ObservationShape a sh:NodeShape ; sh:targetClass jt:EntityObservationState ;\n sh:property [ sh:path jt:observationStateId ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n sh:property [ sh:path jt:forEntity ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:JobPosting ] ;\n sh:property [ sh:path jt:selectsRevision ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:JobPostingRevision ] ;\n sh:property [ sh:path jt:consecutiveAbsenceCount ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:integer ; sh:minInclusive 0 ] ;\n sh:property [ sh:path jt:servingState ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"ACTIVE\" \"EXPIRED\" \"CLOSED\" \"NOT_SEEN\") ] ;\n sh:property [ sh:path jt:firstSeenAt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:dateTime ; sh:lessThanOrEquals jt:lastSeenAt ] ;\n sh:property [ sh:path jt:lastSeenAt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:dateTime ; sh:lessThanOrEquals jt:evaluatedAt ] ;\n sh:property [ sh:path jt:evaluatedAt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:dateTime ] ;\n sh:sparql [ sh:message \"Observation identity/revision/release must match its selected endpoints and release root.\" ; sh:select \"\"\"\n  PREFIX jt: <urn:jobtology:vocab:1:>\n  SELECT $this WHERE {\n   $this jt:forEntity ?entity ; jt:selectsRevision ?revision ; jt:entityId ?eid ; jt:selectedRevisionId ?rid ; jt:releaseId ?release .\n   FILTER (NOT EXISTS { ?entity jt:entityId ?eid ; jt:hasRevision ?revision } ||\n    NOT EXISTS { ?revision jt:revisionId ?rid ; jt:entityId ?eid } ||\n    NOT EXISTS { ?root a jt:CorpusRelease ; jt:selectedReleaseId ?release ; jt:includes $this, ?entity, ?revision })\n  }\"\"\" ] .\n\n\njt:TypedClaimStructureShape a sh:NodeShape ; sh:targetClass jt:RequirementClaim ;\n sh:property [ sh:path jt:claimId ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n sh:property [ sh:path jt:postingRevisionId ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n sh:property [ sh:path jt:evidencedBy ; sh:minCount 1 ; sh:class jt:EvidenceSpan ] ;\n sh:property [ sh:path jt:reviewedBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:RequirementReviewSelection ] ;\n sh:property [ sh:path jt:derivedFrom ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:RequirementNormalization ] ;\n sh:property [ sh:path jt:forSourceGroup ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:SourceRequirementGroup ] ;\n sh:property [ sh:path jt:forSourceAtom ; sh:minCount 1 ; sh:maxCount 1 ; sh:or ([sh:class jt:ConditionExpression] [sh:class jt:SourceRequirementGroup]) ] ;\n sh:property [ sh:path jt:hasSubject ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:JobPostingRevision ] ;\n sh:property [ sh:path [ sh:inversePath jt:hasRequirement ] ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:JobPostingRevision ] ;\n sh:property [ sh:path jt:polarity ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"POSITIVE\" \"NEGATED\" \"NO_CONSTRAINT\") ] ;\n sh:property [ sh:path jt:confidenceState ; sh:hasValue \"UNASSESSED\" ] .\njt:RequirementSelectionShape a sh:NodeShape ; sh:targetClass jt:RequirementReviewSelection ;\n sh:property [ sh:path jt:forSourceAtom ; sh:minCount 1 ; sh:maxCount 1 ; sh:or ([sh:class jt:ConditionExpression] [sh:class jt:SourceRequirementGroup]) ] ;\n sh:property [ sh:path jt:outcome ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"NOT_PROPOSED\" \"PENDING\" \"UNRESOLVED\" \"REJECTED\" \"TARGET_REVISION_MISMATCH\" \"REVIEWED\") ] ;\n sh:property [ sh:path jt:selectsNormalization ; sh:maxCount 1 ; sh:class jt:RequirementNormalization ] .\njt:RequirementProposalShape a sh:NodeShape ; sh:targetClass jt:RequirementNormalization ;\n sh:property [ sh:path jt:normalizationId ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n sh:property [ sh:path jt:hasProposedCondition ; sh:minCount 1 ; sh:maxCount 1 ; sh:or ([sh:class jt:TypedCondition] [sh:class jt:UnresolvedCondition]) ] ;\n sh:property [ sh:path jt:forSourceAtom ; sh:minCount 1 ; sh:maxCount 1 ] ;\n sh:property [ sh:path jt:usesContract ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:RequirementContract ] .\njt:TypedConditionShape a sh:NodeShape ; sh:targetClass jt:TypedCondition ;\n sh:property [ sh:path jt:conditionId ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n sh:property [ sh:path jt:kind ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"SKILL\" \"LANGUAGE\" \"CREDENTIAL\" \"EDUCATION\" \"EXPERIENCE\" \"PROJECT\" \"LOCATION\" \"ELIGIBILITY\" \"AVAILABILITY\") ] .\n\njt:TypedRequirementConditionShape a sh:NodeShape ; sh:targetClass jt:RequirementClaim ;\n  sh:property [ sh:path jt:requirementKind ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"SKILL\" \"CREDENTIAL\" \"EDUCATION\" \"EXPERIENCE\" \"LANGUAGE\" \"PROJECT\" \"LOCATION\" \"ELIGIBILITY\" \"AVAILABILITY\") ] ;\n  sh:property [ sh:path jt:requirementScope ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"CAPABILITY\" \"POSTING_FILTER\") ] ;\n  sh:property [ sh:path jt:necessity ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"REQUIRED\" \"PREFERRED\" \"OPTIONAL\") ] ;\n  sh:property [ sh:path jt:requirementKey ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:xone (\n    [ sh:property [ sh:path jt:requirementKind ; sh:in (\"SKILL\" \"CREDENTIAL\" \"LANGUAGE\") ] ;\n      sh:property [ sh:path jt:targets ; sh:minCount 1 ; sh:maxCount 1 ; sh:or ([ sh:class jt:Skill ] [ sh:class jt:Credential ] [ sh:class jt:NCSCompetencyUnit ]) ] ;\n      sh:property [ sh:path jt:normalizedCondition ; sh:maxCount 0 ] ]\n    [ sh:property [ sh:path jt:requirementKind ; sh:in (\"EDUCATION\" \"EXPERIENCE\" \"PROJECT\" \"LOCATION\" \"ELIGIBILITY\" \"AVAILABILITY\") ] ;\n      sh:property [ sh:path jt:normalizedCondition ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:TypedCondition ] ;\n      sh:property [ sh:path jt:targets ; sh:maxCount 0 ] ]\n  ) ;\n  sh:sparql [ sh:message \"Posting filters must not be counted as capability coverage.\" ;\n    sh:select \"\"\"PREFIX jt: <urn:jobtology:vocab:1:>\n      SELECT $this WHERE { $this jt:requirementKind ?kind ; jt:requirementScope ?scope .\n        FILTER ((?kind IN (\"LOCATION\",\"ELIGIBILITY\",\"AVAILABILITY\") && ?scope != \"POSTING_FILTER\") ||\n          (?kind NOT IN (\"LOCATION\",\"ELIGIBILITY\",\"AVAILABILITY\") && ?scope != \"CAPABILITY\")) }\"\"\" ] ;\n  sh:sparql [ sh:message \"Credential/language requirements must target the matching concept type.\" ;\n    sh:select \"\"\"PREFIX jt: <urn:jobtology:vocab:1:>\n      SELECT $this WHERE { $this jt:requirementKind ?kind ; jt:targets ?target .\n        FILTER ((?kind=\"SKILL\" && NOT EXISTS { ?target a jt:Skill } && NOT EXISTS { ?target a jt:NCSCompetencyUnit }) ||\n          (?kind=\"CREDENTIAL\" && NOT EXISTS { ?target a jt:Credential }) ||\n          (?kind=\"LANGUAGE\" && NOT EXISTS { ?target a jt:Skill ; jt:hasRevision ?v . $this jt:usesTargetBinding ?b . ?b jt:role \"target\" ; jt:targetSubkind \"LANGUAGE\" ; jt:selectsRevision ?v })) }\"\"\" ] .\n\n\n\njt:EditorialSnapshotShape a sh:NodeShape ; sh:targetClass jt:EditorialSourceSnapshot ;\n sh:class jt:SourceSnapshot ;\n sh:property [ sh:path jt:sourceId ; sh:hasValue \"INTERNAL_EDITORIAL\" ] ;\n sh:property [ sh:path jt:sourceText ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ] ;\n sh:property [ sh:path jt:snapshotId ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n sh:property [ sh:path jt:gitBlobSha1 ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern \"^[0-9a-f]{40}$\" ] ;\n sh:property [ sh:path jt:fromSource ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:Source ] ;\n sh:property [ sh:path jt:usesContract ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:EditorialContract ] .\njt:EditorialRecordShape a sh:NodeShape ; sh:targetClass jt:EditorialSourceRecord ;\n sh:class jt:SourceRecordEvidence ;\n sh:property [ sh:path jt:inSnapshot ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:EditorialSourceSnapshot ] ;\n sh:property [ sh:path [ sh:inversePath jt:derivedFrom ] ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:EntityRevision ] .\njt:EditorialSelectionShape a sh:NodeShape ; sh:targetClass jt:EditorialReleaseSelection ;\n sh:property [ sh:path jt:selectsSnapshot ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:EditorialSourceSnapshot ] ;\n sh:property [ sh:path jt:reviewedBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:EditorialReview ] ;\n sh:property [ sh:path jt:selectsRevision ; sh:minCount 5 ; sh:maxCount 5 ; sh:class jt:EntityRevision ] .\njt:EditorialReviewShape a sh:NodeShape ; sh:targetClass jt:EditorialReview ;\n sh:property [ sh:path jt:decision ; sh:hasValue \"ACCEPT\" ] ;\n sh:property [ sh:path jt:reviewerKind ; sh:hasValue \"human\" ] ;\n sh:property [ sh:path jt:reviewedAt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:dateTime ] ;\n sh:property [ sh:path jt:gitCommit ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern \"^([0-9a-f]{40}|[0-9a-f]{64})$\" ] ;\n sh:property [ sh:path jt:mergeEvidence ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n sh:property [ sh:path jt:attestationKind ; sh:hasValue \"OPERATOR_REPORTED\" ] ;\n sh:property [ sh:path jt:repositoryVerification ; sh:hasValue \"NOT_AUTOMATICALLY_VERIFIED\" ] ;\n sh:property [ sh:path jt:forSnapshot ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:EditorialSourceSnapshot ] .\njt:EditorialContractShape a sh:NodeShape ; sh:targetClass jt:EditorialContract ;\n sh:property [ sh:path jt:schemaHash ; sh:minCount 1 ; sh:maxCount 1 ; sh:pattern \"^[0-9a-f]{64}$\" ] .\n\n@prefix jt: <urn:jobtology:vocab:1:> .\n@prefix sh: <http://www.w3.org/ns/shacl#> .\n@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n@prefix schema: <https://schema.org/> .\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\n# Additive publication requirements from implementation-plan.md sections 9–11.\n# Passing shapes alone never replaces the database's remaining publication gates.\njt:PublishedReleaseShape a sh:NodeShape ; sh:targetClass jt:CorpusRelease ;\n  sh:property [ sh:path jt:exportReadMode ; sh:hasValue \"PUBLISHED\" ] ;\n  sh:property [ sh:path jt:releaseState ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"ACTIVE\" \"SUPERSEDED\") ] ;\n  sh:property [ sh:path jt:dataAsOf ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:dateTime ] ;\n  sh:property [ sh:path jt:includes ; sh:qualifiedValueShape [ sh:class jt:Source ] ; sh:qualifiedMinCount 7 ; sh:qualifiedMaxCount 7 ] .\n\njt:PublishedPostingShape a sh:NodeShape ; sh:targetClass jt:JobPostingRevision ;\n  sh:property [ sh:path schema:title ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:minLength 1 ] ;\n  sh:property [ sh:path schema:url ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ] ;\n  sh:property [ sh:path schema:datePosted ; sh:minCount 1 ; sh:maxCount 1 ; sh:or ([ sh:datatype xsd:date ] [ sh:datatype xsd:dateTime ]) ] ;\n  sh:property [ sh:path schema:validThrough ; sh:minCount 1 ; sh:maxCount 1 ; sh:or ([ sh:datatype xsd:date ] [ sh:datatype xsd:dateTime ]) ] ;\n  sh:property [ sh:path jt:sourceStatus ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"OPEN\" \"CLOSED\" \"UNKNOWN\") ] ;\n  sh:property [ sh:path jt:postedBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:Organization ] ;\n  sh:property [ sh:path jt:forOccupation ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:Occupation ] ;\n  sh:property [ sh:path jt:descriptionTextSha256 ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] .\n\njt:PublishedPostingObservationShape a sh:NodeShape ; sh:targetClass jt:JobPosting ;\n  sh:property [ sh:path [ sh:inversePath jt:forEntity ] ; sh:qualifiedValueShape [ sh:class jt:EntityObservationState ] ; sh:qualifiedMinCount 1 ; sh:qualifiedMaxCount 1 ] .\n\njt:PublishedObservationShape a sh:NodeShape ; sh:targetClass jt:EntityObservationState ;\n  sh:property [ sh:path jt:forEntity ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:Entity ] ;\n  sh:property [ sh:path jt:selectsRevision ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:EntityRevision ] ;\n  sh:property [ sh:path jt:servingState ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"ACTIVE\" \"EXPIRED\" \"CLOSED\" \"NOT_SEEN\") ] ;\n  sh:property [ sh:path jt:firstSeenAt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:dateTime ] ;\n  sh:property [ sh:path jt:lastSeenAt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:dateTime ] ;\n  sh:property [ sh:path jt:evaluatedAt ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:dateTime ] .\n\njt:PublishedAssertionShape a sh:NodeShape ; sh:targetClass jt:Assertion ;\n  sh:property [ sh:path jt:confidence ; sh:minCount 1 ; sh:maxCount 1 ; sh:or ([ sh:datatype xsd:decimal ] [ sh:datatype xsd:double ] [ sh:datatype xsd:integer ]) ; sh:minInclusive 0.90 ; sh:maxInclusive 1.0 ] ;\n  sh:property [ sh:path jt:reviewStatus ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"AUTO_ACCEPTED\" \"HUMAN_ACCEPTED\") ] ;\n  sh:property [ sh:path jt:assertionKind ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"SOURCE_EXPLICIT\" \"NORMALIZED\" \"MODEL_INFERRED\") ] ;\n  sh:property [ sh:path jt:evidencedBy ; sh:minCount 1 ; sh:nodeKind sh:IRI ] .\n\njt:PublishedRequirementShape a sh:NodeShape ; sh:targetClass jt:RequirementClaim ;\n  sh:property [ sh:path jt:requirementKind ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"SKILL\" \"CREDENTIAL\" \"EDUCATION\" \"EXPERIENCE\" \"LANGUAGE\" \"PROJECT\" \"LOCATION\" \"ELIGIBILITY\" \"AVAILABILITY\") ] ;\n  sh:property [ sh:path jt:requirementScope ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"CAPABILITY\" \"POSTING_FILTER\") ] ;\n  sh:property [ sh:path jt:necessity ; sh:minCount 1 ; sh:maxCount 1 ; sh:in (\"REQUIRED\" \"PREFERRED\" \"OPTIONAL\") ] ;\n  sh:property [ sh:path jt:requirementKey ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ; sh:pattern \"^[0-9a-f]{64}$\" ] ;\n  sh:xone (\n    [ sh:property [ sh:path jt:requirementKind ; sh:in (\"SKILL\" \"CREDENTIAL\" \"LANGUAGE\") ] ;\n      sh:property [ sh:path jt:targets ; sh:minCount 1 ; sh:maxCount 1 ; sh:or ([ sh:class jt:Skill ] [ sh:class jt:Credential ] [ sh:class jt:NCSCompetencyUnit ]) ] ;\n      sh:property [ sh:path jt:normalizedCondition ; sh:maxCount 0 ] ]\n    [ sh:property [ sh:path jt:requirementKind ; sh:in (\"EDUCATION\" \"EXPERIENCE\" \"PROJECT\" \"LOCATION\" \"ELIGIBILITY\" \"AVAILABILITY\") ] ;\n      sh:property [ sh:path jt:normalizedCondition ; sh:minCount 1 ; sh:maxCount 1 ; sh:class jt:TypedCondition ] ;\n      sh:property [ sh:path jt:targets ; sh:maxCount 0 ] ]\n  ) ;\n  sh:sparql [ sh:message \"Posting filters must not be counted as capability coverage.\" ;\n    sh:select \"\"\"PREFIX jt: <urn:jobtology:vocab:1:>\n      SELECT $this WHERE { $this jt:requirementKind ?kind ; jt:requirementScope ?scope .\n        FILTER ((?kind IN (\"LOCATION\",\"ELIGIBILITY\",\"AVAILABILITY\") && ?scope != \"POSTING_FILTER\") ||\n          (?kind NOT IN (\"LOCATION\",\"ELIGIBILITY\",\"AVAILABILITY\") && ?scope != \"CAPABILITY\")) }\"\"\" ] ;\n  sh:sparql [ sh:message \"Credential/language requirements must target the matching concept type.\" ;\n    sh:select \"\"\"PREFIX jt: <urn:jobtology:vocab:1:>\n      SELECT $this WHERE { $this jt:requirementKind ?kind ; jt:targets ?target .\n        FILTER ((?kind=\"SKILL\" && NOT EXISTS { ?target a jt:Skill } && NOT EXISTS { ?target a jt:NCSCompetencyUnit }) ||\n          (?kind=\"CREDENTIAL\" && NOT EXISTS { ?target a jt:Credential }) ||\n          (?kind=\"LANGUAGE\" && NOT EXISTS { ?target a jt:Skill ; jt:hasRevision ?v . $this jt:usesTargetBinding ?b . ?b jt:role \"target\" ; jt:targetSubkind \"LANGUAGE\" ; jt:selectsRevision ?v })) }\"\"\" ] .\n\n# Detailed condition vocabularies, canonical requirement-key reconstruction,\n# cohort methodology, denominators/support traces and source freshness still\n# require their database implementations and validation. Their absence must not\n# be waived by a passing report from this file.\n\n\njt:PublishedRequirementSelectionShape a sh:NodeShape ; sh:targetClass jt:RequirementReviewSelection ;\n sh:property [ sh:path jt:outcome ; sh:hasValue \"REVIEWED\" ] .\n\n\njt:PublishedEditorialSourceShape a sh:NodeShape ; sh:targetClass jt:CorpusRelease ;\n sh:property [ sh:path jt:includes ; sh:qualifiedValueShape [ sh:class jt:EditorialReleaseSelection ] ; sh:qualifiedMinCount 1 ; sh:qualifiedMaxCount 1 ] .\n"}$contract$::jsonb; BEGIN
 IF EXISTS(SELECT 1 FROM ontology.interchange_contract WHERE version='hop-ontology-interchange-v4' AND artifacts IS DISTINCT FROM package)
 THEN RAISE EXCEPTION 'INTERCHANGE_CONTRACT_VERSION_CONFLICT'; END IF;
 INSERT INTO ontology.interchange_contract(version,artifacts,content_hash)
 VALUES('hop-ontology-interchange-v4',package,ontology.hash(package)) ON CONFLICT DO NOTHING;
